// Package rulesgen derives a Prometheus Operator PrometheusRule manifest from
// the canonical Prometheus rules file, so the two cannot drift.
package rulesgen

import (
	"bytes"
	"fmt"

	"gopkg.in/yaml.v3"
)

// Canonical and generated file locations, relative to the repository root.
const (
	CanonicalPath      = "prometheus/iceberg_exporter.rules.yml"
	PrometheusRulePath = "prometheus/iceberg_exporter.prometheusrule.yaml"
)

// Name is the metadata.name of the generated PrometheusRule.
const Name = "iceberg-exporter"

const header = "# Code generated by tools/genprometheusrule from " + CanonicalPath + ". DO NOT EDIT.\n" +
	"# Regenerate with: make rules-generate\n" +
	"#\n" +
	"# Prometheus Operator only loads PrometheusRules matching its ruleSelector\n" +
	"# (and ruleNamespaceSelector); add the labels your installation expects,\n" +
	"# e.g. with a kustomize patch, rather than editing this file.\n"

// PrometheusRule wraps the canonical rules file (a top-level `groups` list)
// as the spec of a monitoring.coreos.com/v1 PrometheusRule. Comments inside
// the groups are preserved; the canonical file's header comment is replaced.
func PrometheusRule(canonical []byte) ([]byte, error) {
	var doc yaml.Node
	if err := yaml.Unmarshal(canonical, &doc); err != nil {
		return nil, fmt.Errorf("parse rules: %w", err)
	}
	if doc.Kind != yaml.DocumentNode || len(doc.Content) != 1 || doc.Content[0].Kind != yaml.MappingNode {
		return nil, fmt.Errorf("parse rules: expected a mapping document")
	}
	spec := doc.Content[0]
	if len(spec.Content) != 2 || spec.Content[0].Value != "groups" {
		return nil, fmt.Errorf("parse rules: expected exactly one top-level key, groups")
	}
	// Drop the canonical file header wherever the parser attached it.
	spec.HeadComment = ""
	spec.Content[0].HeadComment = ""

	out := mapping(
		"apiVersion", scalar("monitoring.coreos.com/v1"),
		"kind", scalar("PrometheusRule"),
		"metadata", mapping(
			"name", scalar(Name),
			"labels", mapping(
				"app.kubernetes.io/name", scalar("iceberg-exporter"),
			),
		),
		"spec", spec,
	)

	var buf bytes.Buffer
	buf.WriteString(header)
	enc := yaml.NewEncoder(&buf)
	enc.SetIndent(2)
	if err := enc.Encode(out); err != nil {
		return nil, fmt.Errorf("encode PrometheusRule: %w", err)
	}
	if err := enc.Close(); err != nil {
		return nil, fmt.Errorf("encode PrometheusRule: %w", err)
	}
	return buf.Bytes(), nil
}

func scalar(v string) *yaml.Node {
	return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: v}
}

func mapping(kv ...any) *yaml.Node {
	n := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
	for i := 0; i < len(kv); i += 2 {
		n.Content = append(n.Content, scalar(kv[i].(string)), kv[i+1].(*yaml.Node))
	}
	return n
}
